import {database} from './payments.js';
export async function cleanPaymentHistory(db=database()){
 const c=await db.connect();try{await c.query('BEGIN');
 // Purge large notification payloads. Old events cannot be regenerated by flush.
 const notifications=await c.query("DELETE FROM sleepy_payment_notifications WHERE created_at<=now()-interval '7 days'");
 const details=await c.query("UPDATE sleepy_payment_orders SET server_name=NULL,user_name=NULL,installation_error=NULL WHERE COALESCE(paid_at,created_at)<=now()-interval '7 days' AND (server_name IS NOT NULL OR user_name IS NOT NULL OR installation_error IS NOT NULL)");
 // Delete unpaid, expired/rejected history only when it has no entitlement or unresolved payment proof.
 const removable="SELECT o.id FROM sleepy_payment_orders o WHERE o.created_at<=now()-interval '7 days' AND o.status IN ('pending','expired') AND NOT EXISTS(SELECT 1 FROM sleepy_install_entitlements e WHERE e.order_id=o.id) AND NOT EXISTS(SELECT 1 FROM sleepy_payment_attempts a WHERE a.order_id=o.id AND a.status IN ('paid','review','verifying'))";
 await c.query('DELETE FROM sleepy_payment_notifications WHERE order_id IN ('+removable+')');
 // Rejected proof hashes remain while their order exists; paid proof references are never discarded.
 await c.query('DELETE FROM sleepy_payment_attempts WHERE order_id IN ('+removable+')');
 const orders=await c.query('DELETE FROM sleepy_payment_orders WHERE id IN ('+removable+')');
 await c.query('COMMIT');return {notifications:notifications.rowCount,details:details.rowCount,orders:orders.rowCount};
 }catch(e){await c.query('ROLLBACK');throw e;}finally{c.release();}
}
